package com.sellerflow.live;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

/**
 * The native scanner's centre pick (QrCentrePick) against the SAME examples as the web rule
 * (src/lib/qrCentrePick.ts) and the iOS mirror. Cases: QrCentrePickCases (generated by
 * scripts/gen-qr-pick-cases.mjs; a CI test fails when they are stale).
 */
public class QrCentrePickTest {

    private static QrCentrePick.Verdict verdict(String s) {
        if (s.startsWith("one:")) return QrCentrePick.Verdict.one(s.substring(4));
        return "tie".equals(s) ? QrCentrePick.Verdict.TIE : QrCentrePick.Verdict.NONE;
    }

    @Test
    public void constantsMatchTheWebRule() {
        assertEquals(QrCentrePickCases.MARGIN, QrCentrePick.MARGIN, 0);
        assertEquals(QrCentrePickCases.FRAMES, QrCentrePick.FRAMES);
    }

    @Test
    public void everyPickExample() {
        assertTrue(QrCentrePickCases.PICK.length > 0);
        for (QrCentrePickCases.PickCase c : QrCentrePickCases.PICK) {
            assertEquals(c.id, c.expect, QrCentrePick.pick(c.hits, c.frameCx, c.frameCy, c.side).word());
        }
    }

    @Test
    public void everyStreakExample() {
        assertTrue(QrCentrePickCases.STREAK.length > 0);
        for (QrCentrePickCases.StreakCase c : QrCentrePickCases.STREAK) {
            QrCentrePick.Streak streak = null;
            List<String> got = new ArrayList<>();
            for (String s : c.steps) {
                QrCentrePick.Step step = QrCentrePick.step(streak, verdict(s));
                streak = step.streak;
                got.add(step.read != null ? step.read : (step.tie ? "tie" : "-"));
            }
            assertEquals(c.id, Arrays.asList(c.expect), got);
        }
    }

    @Test
    public void fillCentreMappingPortraitPhone() {
        // 960×1280 upright image shown on a 1080×2340 view: scale = max(1.125, 1.828) = 1.828…
        double[] centre = QrCentrePick.mapToView(480, 640, 960, 1280, 1080, 2340, false);
        assertEquals(540, centre[0], 1e-9);
        assertEquals(1170, centre[1], 1e-9);
        double[] corner = QrCentrePick.mapToView(0, 0, 960, 1280, 1080, 2340, false);
        assertEquals((1080 - 960 * (2340.0 / 1280)) / 2, corner[0], 1e-9);
        assertEquals(0, corner[1], 1e-9);
    }

    @Test
    public void frontCameraIsMirrored() {
        double[] p = QrCentrePick.mapToView(100, 640, 960, 1280, 960, 1280, true);
        assertEquals(860, p[0], 1e-9);
        assertEquals(640, p[1], 1e-9);
    }

    @Test
    public void badSizesGiveNaN() {
        assertTrue(Double.isNaN(QrCentrePick.mapToView(1, 1, 0, 10, 10, 10, false)[0]));
    }
}
